def clean_text(text):
    text = re.sub(r"[\[\]\{\}\|]|Unbulleted list|&lt;|&gt;", " ", text)
    text = re.sub(r"\s{2,}", " ", text)
    return text.strip()

def edit_title(title: str):
    title = title.lower()
    title = re.sub(r"\(video game\)", "", title)
    title = "-".join(title.strip().split(" "))

    return title
    
